package com.aditya.ingest.service; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*; @Service public class IngestService { private final RestClient client=RestClient.builder().baseUrl(System.getenv().getOrDefault("SEARCH_URL","http://localhost:8081")).build(); public Object index(Map<String,String> d){return client.post().uri("/api/documents").body(d).retrieve().body(Object.class);} }
